// Colour for the cover.
//
// Cohort lines run along the Nocturne neutral ramp, oldest (dim) to newest
// (light); highlighted risk strata take either the Nocturne accent or a sample
// of one viridis-family colormap.
//
// NOCTURNE is a deliberate copy of the design tokens in
// "PhD Thesis Cover Design_v3/_ds/nocturne-.../styles.css". Keep the two in
// step if that design system is ever updated.

export const NOCTURNE = {
  bg: "#161826",
  surface: "#232532",
  text: "#e9e9ed",
  accent: "#9184d9",
  n200: "#e4e7f5",
  n300: "#cfd3e5",
  n400: "#b2b6ca",
  n500: "#9397ab",
  n600: "#75798c",
  n700: "#595d6c",
  n800: "#3f424d",
  a900: "#2b2741",
} as const;

export const STRATA_PALETTES = [
  "accent",
  "viridis",
  "magma",
  "cividis",
  "turbo",
  "plasma",
  "inferno",
] as const;

export type StrataPalette = (typeof STRATA_PALETTES)[number];

// Frozen 256-entry viridis-family colormaps. Stored as unprefixed six-digit hex
// run together, which keeps the payload at about 9 kB of compressible text and
// protects the colors used by the established cover fixtures.
const RAMPS: Record<Exclude<StrataPalette, "accent">, string> = {
  viridis:
    "",
  magma:
    "",
  cividis:
    "",
  turbo:
    "",
  plasma:
    "",
  inferno:
    "",
};

/**
 * Round half to even, preserving the established cover's color calculations.
 *
 * JavaScript's `Math.round` rounds a half up instead, and the difference is
 * not academic: mixing #3f424d toward #75798c lands a channel on exactly 78.5,
 * and sampling a colormap at position 0.3 lands the index on exactly 76.5.
 * Rounding those the other way shifts a cohort line and a stratum by one step.
 */
function roundHalfEven(x: number): number {
  const floor = Math.floor(x);
  const frac = x - floor;
  if (frac > 0.5) return floor + 1;
  if (frac < 0.5) return floor;
  return floor % 2 === 0 ? floor : floor + 1;
}

/** Look up entry `i` of a packed 256-colour ramp. */
function rampColour(palette: Exclude<StrataPalette, "accent">, i: number): string {
  const packed = RAMPS[palette];
  return "#" + packed.slice(i * 6, i * 6 + 6);
}

function channels(hex: string): [number, number, number] {
  const n = parseInt(hex.slice(1), 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

function toHex(r: number, g: number, b: number): string {
  const byte = (v: number) =>
    roundHalfEven(Math.min(255, Math.max(0, v))).toString(16).padStart(2, "0");
  return `#${byte(r)}${byte(g)}${byte(b)}`;
}

/**
 * Interpolate between two colours in sRGB.
 *
 * Deliberately sRGB rather than a perceptually uniform space, because the
 * published covers were built with a straight channel-wise mix and switching
 * spaces would shift every line.
 */
export function blendSrgb(from: string, to: string, t: number): string {
  const a = channels(from);
  const b = channels(to);
  return toHex(
    a[0] + (b[0] - a[0]) * t,
    a[1] + (b[1] - a[1]) * t,
    a[2] + (b[2] - a[2]) * t,
  );
}

/**
 * Colour a cohort line by its rank within the stack.
 *
 * @param rank 0 is the oldest cohort, 1 the newest.
 */
export function cohortColour(rank: number): string {
  return rank <= 0.55
    ? blendSrgb(NOCTURNE.n800, NOCTURNE.n600, Math.min(1, rank / 0.55))
    : blendSrgb(NOCTURNE.n600, NOCTURNE.n200, Math.max(0, (rank - 0.55) / 0.45));
}

/**
 * Sample a viridis-family colormap.
 *
 * @param palette One of STRATA_PALETTES. "accent" ignores `t`.
 * @param t Position along the colormap in [0, 1].
 */
export function strataColour(palette: StrataPalette, t: number): string {
  if (!STRATA_PALETTES.includes(palette)) {
    throw new Error(
      `\`palette\` must be one of ${STRATA_PALETTES.join(", ")}, not "${palette}".`,
    );
  }
  if (palette === "accent") return NOCTURNE.accent;
  return rampColour(palette, roundHalfEven(Math.min(1, Math.max(0, t)) * 255));
}
